/* The bar plot's figure is explicitly sized wider than its column once there
   are many models (see _BAR_WIDTH_PER_MODEL in app.py) — scroll it
   horizontally instead of squeezing every bar into the visible width. */
#leaderboard-bar-plot .plot-container,
#leaderboard-bar-plot .js-plotly-plot {
    overflow-x: auto;
}

/* Zoom/pan is disabled on this chart (fixedrange + dragmode=False in
   app.py), so its zoom/pan/autoscale toolbar would only be dead weight. */
#leaderboard-bar-plot .modebar {
    display: none;
}

#leaderboard-table th,
#leaderboard-table td {
    min-width: 70px;
}

#leaderboard-table th .header-content {
    white-space: nowrap;
}

#leaderboard-table td {
    white-space: nowrap;
    overflow: visible !important;
    text-overflow: clip !important;
    max-width: none !important;
}

#leaderboard-table {
    width: 100% !important;
    table-layout: auto !important;
}

#multilingual-table th,
#multilingual-table td {
    min-width: 70px;
}

#multilingual-table th .header-content {
    white-space: nowrap;
}

#multilingual-table td {
    white-space: nowrap;
    overflow: visible !important;
    text-overflow: clip !important;
    max-width: none !important;
}

#multilingual-table {
    width: 100% !important;
    table-layout: auto !important;
}

#multilingual-table th:hover {
    background-color: var(--table-row-focus);
}

#longform-table th,
#longform-table td {
    min-width: 70px;
