#longform-table th:hover {
    background-color: var(--table-row-focus);
}

#private-data-table th,
#private-data-table td {
    min-width: 70px;
}

#private-data-table th .header-content {
    white-space: nowrap;
}

#private-data-table td {
    white-space: nowrap;
    overflow: visible !important;
    text-overflow: clip !important;
    max-width: none !important;
}

#private-data-table {
    width: 100% !important;
    table-layout: auto !important;
}

#private-data-table th:hover {
    background-color: var(--table-row-focus);
}

.language-detail-modal {
    background: var(--background-fill-primary);
    border: 1px solid var(--border-color-primary);
    border-radius: 8px;
    padding: 1rem;
    margin: 1rem 0;
}

.promo-banner {
    background: var(--color-accent-soft);
    border: 1px solid var(--border-color-accent);
    border-radius: 8px;
    padding: 0.75rem 1rem;
    margin: 0.5rem 0 1rem 0;
    text-align: center;
    font-size: 1.05em;
}
.promo-banner a {
    color: var(--link-text-color);
}

/* Center the leftmost "Rank" column (header + cells) on every table. */
#leaderboard-table th:first-child,
#leaderboard-table td:first-child,
#multilingual-table th:first-child,
#multilingual-table td:first-child,
#longform-table th:first-child,
#longform-table td:first-child,
#private-data-table th:first-child,
#private-data-table td:first-child {
    text-align: center;
}
#leaderboard-table th:first-child .header-content,
#leaderboard-table th:first-child .header-button,
#multilingual-table th:first-child .header-content,
#multilingual-table th:first-child .header-button,
#longform-table th:first-child .header-content,
#longform-table th:first-child .header-button,
#private-data-table th:first-child .header-content,
#private-data-table th:first-child .header-button {
    justify-content: center;
    text-align: center;
}

/* Center the "Rank Δ" column (header + cells) — main leaderboard only. */
#leaderboard-table th:nth-child(2),
#leaderboard-table td:nth-child(2) {
    text-align: center;
}
#leaderboard-table th:nth-child(2) .header-content,
#leaderboard-table th:nth-child(2) .header-button {
    justify-content: center;
    text-align: center;
}

/* Narrow the "Model" column on the main leaderboard (3rd column: Rank, Rank Δ,
   Model) and private-data tables (2nd column: Rank, Model) so long model
   names wrap instead of stretching the whole table. */
#leaderboard-table th:nth-child(3),
#leaderboard-table td:nth-child(3),
#private-data-table th:nth-child(2),
#private-data-table td:nth-child(2) {
    width: 260px !important;
    min-width: 260px !important;
    max-width: 260px !important;
    white-space: normal !important;
}

.tab-link-icon {
    text-decoration: none; font-size: 0.8em; opacity: 0.45; cursor: pointer;
    margin-left: 0.35em; vertical-align: middle; user-select: none;
}
.tab-link-icon:hover { opacity: 1; }
.hidden-trigger { display: none !important; }

