() => {
  const slugs = ["leaderboard", "multilingual", "longform", "private", "pareto", "benchmark-fitting", "about"];
  // Delegated listeners so they survive re-renders and load-order timing.
  // 1) Tab clicks -> ?tab= query param.
  document.addEventListener('click', (e) => {
    const nav = document.querySelector('.tab-buttons .tab-nav') ||
                document.querySelector('.tab-buttons [role="tablist"]');
    if (!nav) return;
    const btn = e.target.closest('button');
    if (!btn || !nav.contains(btn)) return;
    const i = Array.from(nav.querySelectorAll('button')).indexOf(btn);
    if (i < 0 || !slugs[i]) return;
    const url = new URL(window.location.href);
    url.searchParams.set('tab', slugs[i]);
    // ?proprietary= and ?languages= are one-time bootstraps (see
    // _select_url_params) for whichever tab they're loaded with —
    // once the user switches tabs they no longer describe the
    // current tab, so drop them.
    url.searchParams.delete('proprietary');
    url.searchParams.delete('languages');
    url.hash = '';  // drop any leftover in-page anchor (e.g. #bf-ref-errors)
    window.history.replaceState(null, '', url);
  });
  // 2) In-page "Jump to" links -> smooth scroll. Native #hash anchor
  //    navigation is unreliable inside the Spaces iframe / Gradio SPA,
  //    so scroll the target element into view ourselves.
  document.addEventListener('click', (e) => {
    const link = e.target.closest('a[href^="#"]');
    if (!link) return;
    const id = decodeURIComponent((link.getAttribute('href') || '').slice(1));
    const target = id && document.getElementById(id);
    if (!target) return;
    e.preventDefault();
    target.scrollIntoView({behavior: 'smooth', block: 'start'});
  });
  // 3) Inline 🔗 title icons (span#copy-tab-<slug>) -> copy this tab's
  //    deep link, then fire the "copied" toast via the hidden trigger.
  document.addEventListener('click', (e) => {
    const el = e.target.closest('.tab-link-icon[id^="copy-tab-"]');
    if (!el) return;
    e.preventDefault();
    const slug = el.id.replace('copy-tab-', '');
    navigator.clipboard.writeText(
      window.location.origin + window.location.pathname + '?tab=' + slug);
    const trigger = document.getElementById('copy-toast-trigger');
    if (trigger) trigger.click();
  });
  // 4) Clicking a bar in the leaderboard bar plot -> copy its
  //    breakdown as a Markdown table (see _bar_markdown_row, carried
  //    per-point as customdata — plain text already, no tags to
  //    strip) and fire its own "copied" toast. Bound via Plotly's own
  //    plotly_click event (not DOM delegation, since that's per-point
  //    data Plotly itself tracks) directly on the plot element; a
  //    MutationObserver re-attaches it if the element is ever
  //    recreated (a plain data update reuses it, so this normally
  //    only fires once).
  function attachBarPlotCopy() {
    const plotEl = document.querySelector('#leaderboard-bar-plot .js-plotly-plot');
    if (!plotEl || plotEl.dataset.copyBound || !plotEl.on) return;
    plotEl.dataset.copyBound = '1';
    plotEl.on('plotly_click', (data) => {
      const pt = data.points && data.points[0];
      if (!pt || pt.customdata == null) return;
      navigator.clipboard.writeText(pt.customdata);
      const trigger = document.getElementById('copy-stats-toast-trigger');
      if (trigger) trigger.click();
    });
  }
  attachBarPlotCopy();
  new MutationObserver(attachBarPlotCopy).observe(document.body, {childList: true, subtree: true});
}
